insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('eecbc978-beda-4a40-be50-bc85cabd50bf', '0cdb5672-3c7b-43ec-b395-d911ec217a16', $$inleiding: zorgbehandelingen bij zorgaanbieders; overheid bewaakt kwaliteit$$,
   $$economie-vwo-2025-i-zorgverzekering-context1.png$$,
   $$In een land gaan inwoners voor zorgbehandelingen naar zorgaanbieders zoals huisartsen, fysiotherapeuten of ziekenhuizen. De overheid van het land bewaakt en controleert de kwaliteit van de geleverde zorg.$$, 'inline'),
  ('d90132ce-ee08-4bde-8fcb-a8cbb51223df', '0cdb5672-3c7b-43ec-b395-d911ec217a16', $$verplichte zorgverzekering; verzekeraars mogen niet weigeren en kennen risico’s niet$$,
   $$economie-vwo-2025-i-zorgverzekering-context2.png$$,
   $$De overheid vindt dat iedereen in het land recht heeft op gezondheidszorg. Om de kosten te kunnen dekken, komt er een verplichte zorgverzekering. Zorgverzekeraars kunnen verzekerden niet weigeren. Verzekerden betalen maandelijks premie aan een zorgverzekeraar. De zorgverzekeraars zijn niet in staat om vooraf te bepalen of de verzekerden goede of slechte risico’s zijn.$$, 'inline'),
  ('5a0542a2-4211-4c6b-9f16-5de95e101730', '0cdb5672-3c7b-43ec-b395-d911ec217a16', $$econoom bekijkt de Zoohee! zorgverzekering voor jongeren met eigen risico$$,
   $$economie-vwo-2025-i-zorgverzekering-context3.png$$,
   $$Een econoom onderzoekt de zorgverzekeringsmarkt en bekijkt de Zoohee! zorgverzekering voor jongeren. Bij deze verzekering geldt een eigen risico.$$, 'inline'),
  ('954db4b0-2bbc-44eb-8860-7a94ee537f77', '0cdb5672-3c7b-43ec-b395-d911ec217a16', $$tabel 1: Zoohee! zorgverzekering (wettelijk vs. verhoogd eigen risico)$$,
   $$economie-vwo-2025-i-zorgverzekering-context4.png$$,
   $$Tabel 1 Zoohee! zorgverzekering
met wettelijk eigen risico | met verhoogd eigen risico
eigen risico: € 385 per jaar | eigen risico: € 885 per jaar
premie: € 108,25 per maand | premie: € 86,25 per maand$$, 'inline'),
  ('64923b89-9c7c-4b3e-92fe-4bed0d0c9124', '0cdb5672-3c7b-43ec-b395-d911ec217a16', $$jongeren: weinig zorgkosten; totale zorgkosten = premie + zorgkosten binnen eigen risico$$,
   $$economie-vwo-2025-i-zorgverzekering-context5.png$$,
   $$Jongeren hebben over het algemeen weinig zorgkosten. Het kan voordelig zijn om een verhoogd eigen risico te nemen. De totale zorgkosten voor een jongere bestaan uit de premie en de zorgkosten die binnen het eigen risico worden gemaakt.$$, 'inline'),
  ('47a98db0-b14f-44b8-8057-18234d04d9d1', '0cdb5672-3c7b-43ec-b395-d911ec217a16', $$eigen risico geldt niet meer voor huisartsbezoeken$$,
   $$economie-vwo-2025-i-zorgverzekering-context6.png$$,
   $$De totale zorgkosten in het land nemen toe. De overheid besluit daarom dat het eigen risico niet meer geldt voor huisartsbezoeken. Uit onderzoek blijkt dat daardoor de totale zorgkosten kunnen afnemen.$$, 'inline'),
  ('bce73d76-8ef4-416f-aec4-e6e00a0bda9f', '0cdb5672-3c7b-43ec-b395-d911ec217a16', $$heterogeen oligopolie van zorgverzekeraars en vergelijkingssites$$,
   $$economie-vwo-2025-i-zorgverzekering-context7.png$$,
   $$Zorgverzekeraars zijn actief op een heterogene oligopolistische markt, waarbij hun zorgverzekeringen verschillen in voorwaarden en premies. Vergelijkingssites vergelijken deze voorwaarden en premies van de verschillende zorgverzekeringen. Consumenten kunnen via zo’n vergelijkingssite een zorgverzekering afsluiten.$$, 'inline'),
  ('5134df36-befc-4e87-883b-8b328d70ff04', '0cdb5672-3c7b-43ec-b395-d911ec217a16', $$vaste vergoeding per afgesloten verzekering aan vergelijkingssite; stelling econoom$$,
   $$economie-vwo-2025-i-zorgverzekering-context8.png$$,
   $$Per afgesloten verzekering betalen zorgverzekeraars een vaste vergoeding aan een vergelijkingssite. De econoom: “Uit mijn onderzoek blijkt dat vergelijkingssites onderhandelen met de verzekeraars over de hoogte van de (vaste) vergoeding per afgesloten verzekering. Hierdoor ontstaat een principaal-agentprobleem tussen de consument (de principaal) en de vergelijkingssite (de agent).”$$, 'inline'),
  ('bde7e26f-00c5-4775-9864-cd82e49a659a', 'ab404e6a-0f51-4e37-a480-4f12e1aee162', $$inleiding: waardevast staatspensioen (omslagstelsel) en aanvullend pensioen (kapitaaldekking) tot 70% van het laatste loon$$,
   $$economie-vwo-2025-i-concurreren-met-zekerheid-context1.png$$,
   $$Het land Mañan heeft een waardevast staatspensioen dat via het omslagstelsel wordt gefinancierd. Het aanvullend pensioen belooft dit staatspensioen aan te vullen tot een vast, totaalbedrag van 70% van het laatstverdiende (nominale) brutoloon. Het totale pensioen is daarmee niet waardevast. Werknemers moeten een aanvullend pensioen opbouwen bij één van de commerciële pensioenfondsen die het kapitaaldekkingsstelsel gebruiken. De nominale brutolonen veranderen niet.$$, 'inline'),
  ('fb91dd04-a787-47c0-b5fa-d09e479fcba1', 'ab404e6a-0f51-4e37-a480-4f12e1aee162', $$pensioenfondsen beleggen in aandelen en obligaties en concurreren op premie$$,
   $$economie-vwo-2025-i-concurreren-met-zekerheid-context2.png$$,
   $$De pensioenfondsen beleggen hun vermogen in aandelen en obligaties. Pensioenfondsen concurreren met elkaar (= marktwerking) op basis van de ingelegde pensioenpremie. Werknemers ontvangen alleen informatie over de verhouding tussen obligaties en aandelen waarin een pensioenfonds belegt en de maandelijkse premie die ze moeten betalen. In Mañan kunnen werknemers wisselen van pensioenaanbieder.$$, 'inline'),
  ('f78f8e29-cedb-4508-958c-b4c628fd0149', 'ab404e6a-0f51-4e37-a480-4f12e1aee162', $$figuur 1 toont de factoren op de markt voor aanvullende pensioenen$$,
   $$economie-vwo-2025-i-concurreren-met-zekerheid-context3.png$$,
   $$Figuur 1 toont de relevante factoren binnen de markt voor aanvullende pensioenen.$$, 'inline'),
  ('d8fece83-9ee4-4850-8423-2d2baac11fe6', 'ab404e6a-0f51-4e37-a480-4f12e1aee162', $$figuur 1: factoren die de hoogte van de aanvullende pensioenen beïnvloeden; formule dekkingsgraad$$,
   $$economie-vwo-2025-i-concurreren-met-zekerheid-context4.png$$,
   $$Figuur 1 Factoren die de hoogte van de aanvullende pensioenen beïnvloeden
Schema met pijlen: marktwerking → bedrijfskosten; bedrijfskosten → dekkingsgraad; marktwerking → premie aanvullend pensioen (pijl via de linkerkant); premie aanvullend pensioen ↔ dekkingsgraad; dekkingsgraad ↔ uitkering aanvullend pensioen; bedrijfskosten → uitkering aanvullend pensioen (pijl via de rechterkant); inflatie ↔ rentestand centrale bank; rentestand centrale bank → dekkingsgraad.
dekkingsgraad = (huidig vermogen pensioenfonds / huidige waarde toekomstige pensioenuitkeringen) x 100%$$, 'inline'),
  ('8c08c219-d656-4465-8e2d-2bc4e8dc6615', 'ab404e6a-0f51-4e37-a480-4f12e1aee162', $$inflatie hoger dan gewenst door de centrale bank$$,
   $$economie-vwo-2025-i-concurreren-met-zekerheid-context5.png$$,
   $$Stel dat de inflatie hoger wordt dan de gewenste inflatie van de centrale bank.$$, 'inline'),
  ('ce99ccb7-9267-45ee-ad70-56150a3f40c0', 'ab404e6a-0f51-4e37-a480-4f12e1aee162', $$pensioenfondsen hebben over 25 jaar € 450 miljard nodig; dekkingsgraad 92% bij 1% rente; rente stijgt naar 2%$$,
   $$economie-vwo-2025-i-concurreren-met-zekerheid-context6.png$$,
   $$Naar verwachting hebben de pensioenfondsen over 25 jaar een bedrag nodig van € 450 miljard. Momenteel is de gemiddelde dekkingsgraad van alle pensioenfondsen samen gelijk aan 92%, waarbij wordt uitgegaan van een rente van 1%. Men verwacht dat de rente stijgt naar 2%. Dit leidt tot een nieuwe dekkingsgraad.$$, 'inline'),
  ('d74d1231-8735-4ad0-a919-8a3e0c5f2fce', '4101a9fc-7b6b-4298-8ac6-c187546a7ba7', $$inleiding: ijssalon Guarda heeft een monopoliepositie$$,
   $$economie-vwo-2025-i-ijssalon-context1.png$$,
   $$Een onderneemster opent in 2023 ijssalon Guarda. Guarda is de eerste ijssalon binnen een groot gebied, waardoor ze een monopoliepositie heeft. Op basis van een marktonderzoek heeft Guarda de vraag naar ijsjes bepaald (zie tabel 1 en figuur 1).$$, 'inline'),
  ('53daa2ea-8a2f-46a1-9484-29326ce03bff', '4101a9fc-7b6b-4298-8ac6-c187546a7ba7', $$tabel 1: gegevens marktonderzoek Guarda (vraag- en kostenfunctie)$$,
   $$economie-vwo-2025-i-ijssalon-context2.png$$,
   $$Tabel 1 Gegevens marktonderzoek Guarda
Qv = –50P + 210 | Qv = vraag naar ijsjes in duizenden; P = prijs per ijsje in euro’s
TK = 0,005Q² + 1,2Q + 30 | TK = totale kosten in duizenden euro’s; Q = het aantal ijsjes in duizenden$$, 'inline'),
  ('76db0f4d-15dd-438e-af84-c3d1173b6546', '4101a9fc-7b6b-4298-8ac6-c187546a7ba7', $$figuur 1: opbrengsten en kostenfuncties van Guarda$$,
   $$economie-vwo-2025-i-ijssalon-context3.png$$,
   $$Figuur 1 Opbrengsten en kostenfuncties van Guarda
verticale as: P, GO, GVK en GTK (in €); horizontale as: Q (x 1.000), 0 tot 220.
GO: dalende lijn van 4,2 bij Q = 0 naar 0 bij Q = 210.
GVK: stijgende lijn vanaf 1,2 bij Q = 0.
GTK: dalende curve die vanaf ongeveer Q = 80 langzaam stijgt, boven de GVK-lijn.$$, 'inline'),
  ('917fc8ae-649d-431d-b1df-bf86ec72f017', '4101a9fc-7b6b-4298-8ac6-c187546a7ba7', $$Guarda behaalt maximale winst bij een prijs van € 3$$,
   $$economie-vwo-2025-i-ijssalon-context4.png$$,
   $$Guarda behaalt maximale winst bij een prijs van € 3 per ijsje.$$, 'inline'),
  ('a191a5c1-e4e8-4481-ad8b-aaf4be759cc8', '4101a9fc-7b6b-4298-8ac6-c187546a7ba7', $$in 2024 stijgen de variabele kosten met € 0,25 per ijsje$$,
   $$economie-vwo-2025-i-ijssalon-context5.png$$,
   $$In 2024 stijgen voor Guarda de variabele kosten ten opzichte van 2023 met € 0,25 per ijsje. De overige gegevens blijven hetzelfde.$$, 'inline'),
  ('0fce856e-ed4a-4d9a-a2a5-eb9d42d2081a', '4101a9fc-7b6b-4298-8ac6-c187546a7ba7', $$toetreding Orso Bianco; ijsjes zijn perfecte substituten$$,
   $$economie-vwo-2025-i-ijssalon-context6.png$$,
   $$Begin 2025 raakt Guarda de monopoliepositie kwijt door de opening van ijssalon Orso Bianco. Deze ijssalon heeft dezelfde productiekosten als Guarda. Orso Bianco treedt toe met een lagere prijs. Consumenten zien de ijsjes van Orso Bianco als perfect substituut voor de ijsjes van Guarda, waardoor beide salons via een prijzenoorlog in een gevangenendilemma kunnen belanden.$$, 'inline'),
  ('5eba0177-5460-4f07-84f2-43f392c8e17c', '4101a9fc-7b6b-4298-8ac6-c187546a7ba7', $$zelfbinding via vaste verkoopprijs en laagsteprijsgarantie$$,
   $$economie-vwo-2025-i-ijssalon-context7.png$$,
   $$Guarda wil een prijzenoorlog vermijden. Guarda past zelfbinding toe door advertenties op sociale media te plaatsen. In deze advertenties staat een vaste verkoopprijs voor 2025, in combinatie met een laagsteprijsgarantie. Dit houdt het volgende in: als consumenten een ijsje voor een lagere prijs kunnen krijgen bij concurrent Orso Bianco, dan geeft Guarda een korting van 25% op die lagere prijs.$$, 'inline'),
  ('b7476558-a130-4cdf-8e22-e7d3efb13cc4', '4101a9fc-7b6b-4298-8ac6-c187546a7ba7', $$uitwerkbijlage vraag 13: figuur 1$$,
   $$economie-vwo-2025-i-ijssalon-context8.png$$,
   $$uitwerkbijlage vraag 13
Figuur 1 (kopie van figuur 1 met GO, GVK en GTK)$$, 'uitwerkbijlage'),
  ('33bb6659-488f-4aa5-9916-5c29c4b19733', 'a189ee78-f2a6-4f3d-8848-6ebfc8358251', $$inleiding: korte-termijnmodel voor Curaçao met handelspartner Aruba (XCG en AWG)$$,
   $$economie-vwo-2025-i-eilanden-verbonden-context1.png$$,
   $$De ministers van Economische Ontwikkeling van de Caribische eilanden willen meer met elkaar handelen. Om deze wens te onderzoeken stelt een econoom een korte-termijnmodel op voor Curaçao (zie figuur 1). Voor de eenvoud is Aruba de enige handelspartner van Curaçao. In het model is de munteenheid van Curaçao de Caribische gulden (XCG) en de munteenheid van Aruba de Arubaanse florin (AWG).$$, 'inline'),
  ('3a4f95f2-7d89-4137-8d0d-0d705e4fcd1e', 'a189ee78-f2a6-4f3d-8848-6ebfc8358251', $$arbeidsinkomen is de inkomstenbron van de gezinnen$$,
   $$economie-vwo-2025-i-eilanden-verbonden-context2.png$$,
   $$In het model is het arbeidsinkomen de inkomstenbron van de gezinnen op Curaçao.$$, 'inline'),
  ('e0e56e36-b96f-4836-adf7-7afcd3748bec', 'a189ee78-f2a6-4f3d-8848-6ebfc8358251', $$overheid niet getoond, overheidssaldo wel te berekenen$$,
   $$economie-vwo-2025-i-eilanden-verbonden-context3.png$$,
   $$De Curaçaose overheid is niet getoond in het model, maar het overheidssaldo kan wel worden berekend.$$, 'inline'),
  ('6642a01b-0884-487c-b0ca-bc0af1926717', 'a189ee78-f2a6-4f3d-8848-6ebfc8358251', $$vraag naar arbeid in Curaçao stijgt; loonkosten stijgen$$,
   $$economie-vwo-2025-i-eilanden-verbonden-context4.png$$,
   $$In Curaçao stijgt de vraag naar arbeid, waardoor de loonkosten stijgen. De econoom wil uitzoeken wat de gevolgen zijn voor het inflatieniveau op Aruba.$$, 'inline'),
  ('2013682b-4154-4a31-9b0f-4e9f6759da38', 'a189ee78-f2a6-4f3d-8848-6ebfc8358251', $$centrale bank van Curaçao voert ruimer monetair beleid$$,
   $$economie-vwo-2025-i-eilanden-verbonden-context5.png$$,
   $$De centrale bank van Curaçao besluit een ruimer monetair beleid te voeren.$$, 'inline'),
  ('ed2fa49b-b77f-415a-9fc8-09a952f4ab69', 'a189ee78-f2a6-4f3d-8848-6ebfc8358251', $$figuur 1: factoren beïnvloeding Curaçaose en Arubaanse economie$$,
   $$economie-vwo-2025-i-eilanden-verbonden-context6.png$$,
   $$Figuur 1 Factoren beïnvloeding Curaçaose en Arubaanse economie
Arbeidsmarkt Curaçao: loon (in XCG) tegen arbeidsjaren (x 1.000); Qa en Qv snijden bij loon 26.000 en 120 (x 1.000) arbeidsjaren.
Vermogensmarkt Curaçao: rente tegen Q (in miljoenen XCG); evenwicht bij 3% en Q = 9.
Goederen- en dienstenmarkt Curaçao: inflatie tegen Y (in miljarden XCG); GA en GV snijden bij 2% en Y = 5,45.
Goederen- en dienstenmarkt Aruba: inflatie tegen Y (in miljoenen florin); GA en GV snijden bij π en Y.
Geldstromen: S = 664 mln. (van arbeidsmarkt naar vermogensmarkt), C = 3.960 mln. (naar goederen- en dienstenmarkt Curaçao), I = 1.200 mln. (van vermogensmarkt naar goederen- en dienstenmarkt Curaçao), E = 250 mln. (van Aruba naar Curaçao), M = 860 mln. (van Curaçao naar Aruba).
Legenda: GA = geaggregeerd aanbod; GV = geaggregeerde vraag, dit bestaat uit de totale bestedingen: C + I + O + E - M. De C, I, O, E, M en S zijn geldstromen in Caribische guldens (XCG), waarbij: C = particuliere consumptie, I = investeringen, O = overheidsbestedingen, E = export, M = import, S = particuliere besparingen. De pijlen zijn geldstromen in Caribische guldens (XCG).$$, 'inline'),
  ('8cc8fef7-dad7-4bbf-8105-805e9ccb6f9a', 'a189ee78-f2a6-4f3d-8848-6ebfc8358251', $$uitwerkbijlage vraag 19: figuur 1 en tabel veranderingen evenwichtsprijzen$$,
   $$economie-vwo-2025-i-eilanden-verbonden-context7.png$$,
   $$uitwerkbijlage vraag 19
Figuur 1 (kopie van figuur 1)
Veranderingen evenwichtsprijzen (Vul in: stijgt of daalt)
loonniveau Curaçao | ...
inflatie Curaçao | ...
inflatie Aruba | ...$$, 'uitwerkbijlage'),
  ('636eb785-8662-49a2-867d-9042e7dccd9f', 'a5aa7389-530d-4a58-a529-5940624030d0', $$inleiding: huishoudens consumeren minder; analyse met Keynesiaans kruis$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context1.png$$,
   $$In een land is de huidige consumptie niet duurzaam ten opzichte van wat de aarde aankan. Huishoudens besluiten hun verantwoordelijkheid te nemen en minder te consumeren. Een econoom analyseert de effecten van deze gedragsverandering met behulp van het Keynesiaanse kruis (zie figuur 1).$$, 'inline'),
  ('36892356-11b2-4798-91e2-cc00fcefc513', 'a5aa7389-530d-4a58-a529-5940624030d0', $$figuur 1: Keynesiaans kruis met EV₀ en EV₁$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context2.png$$,
   $$Figuur 1 Keynesiaans kruis
verticale as: EV = effectieve vraag in mld €; horizontale as: bbp in mld (0 tot 1.000).
Lijnen Y = EV, EV₀ en EV₁; EV₀ snijdt de lijn Y = EV bij 800 (Y₀ = Y*).
EV₀ = oude effectieve vraag (voor de gedragsverandering) = 400 + 0,5Y
EV₁ = nieuwe effectieve vraag (na de gedragsverandering) = 360 + 0,4Y$$, 'inline'),
  ('213796eb-36dd-49aa-bc9a-4ce7c5f8e2ab', 'a5aa7389-530d-4a58-a529-5940624030d0', $$stelling econoom: ligging en helling van de EV₁-curve veranderd$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context3.png$$,
   $$De econoom stelt: “Door de gedragsverandering van consumenten is zowel de ligging als de helling van de EV₁-curve veranderd ten opzichte van de EV₀-curve.”$$, 'inline'),
  ('d88db032-9528-499b-8274-e2daa11b7cd7', 'a5aa7389-530d-4a58-a529-5940624030d0', $$negatieve output gap; keuze tussen begrotingsbeleid en monetair beleid$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context4.png$$,
   $$Door de gedragsverandering ontstaat een negatieve output gap. De econoom analyseert twee maatregelen: het voeren van begrotingsbeleid of monetair beleid.$$, 'inline'),
  ('8b86648b-502e-4812-814f-0e42bdc9e2a6', 'a5aa7389-530d-4a58-a529-5940624030d0', $$hogere overheidsbestedingen hebben twee gevolgen voor het groen bbp$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context5.png$$,
   $$De overheid kan de overheidsbestedingen verhogen. Dit heeft twee gevolgen voor het groen bbp.$$, 'inline'),
  ('c6364516-c35c-4077-8e2b-c40a7966ee8e', 'a5aa7389-530d-4a58-a529-5940624030d0', $$econoom analyseert monetair beleid met een nieuw model$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context6.png$$,
   $$De econoom wil ook analyseren of het monetaire beleid invloed heeft na de gedragsverandering. De econoom schetst daarom een nieuw model (zie figuur 2).$$, 'inline'),
  ('f7ca8cf4-ed06-4cd4-aa0d-246f0db062ae', 'a5aa7389-530d-4a58-a529-5940624030d0', $$figuur 2: IS-MB-model met IS₀ en IS₁$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context7.png$$,
   $$Figuur 2 IS-MB-model
verticale as: r = reële rente in %; horizontale as: Y = inkomen (0 tot 1.000; 800 = Y*).
Horizontale MB-lijn bij r = 4%. IS₀ snijdt MB bij Y = 800; de steilere IS₁ snijdt MB bij Y = 600.
IS₀ = IS-curve voor de gedragsverandering
IS₁ = IS-curve na de gedragsverandering$$, 'inline'),
  ('741397a8-048f-41a2-9e05-61cda2b5bd28', 'a5aa7389-530d-4a58-a529-5940624030d0', $$helling van de IS-curve veranderd; effectiviteit monetair beleid$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context8.png$$,
   $$Door de gedragsverandering is de helling van de IS-curve veranderd. Dit heeft effect op de effectiviteit van monetair beleid.$$, 'inline'),
  ('784fa69e-aaf9-46cd-b73f-f37316a258cb', 'a5aa7389-530d-4a58-a529-5940624030d0', $$conclusie econoom: monetair beleid brengt de economie terug in het oude evenwicht$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context9.png$$,
   $$De econoom concludeert: “In dit model zal monetair beleid ervoor zorgen dat de economie weer terugkeert in het oude evenwicht van voor de gedragsverandering.”$$, 'inline'),
  ('88d4dae4-149e-45c3-9807-93bcb87a76ca', 'a5aa7389-530d-4a58-a529-5940624030d0', $$sociale norm: minder consumeren; potentieel inkomen naar Y* = 600 miljard; stelling econoom$$,
   $$economie-vwo-2025-i-groen-ontgroeien-context10.png$$,
   $$Consumenten hebben een sociale norm uitgesproken: zij gaan minder consumeren en dus is een lager inkomen voor hen voldoende. De overheid kan via deze sociale norm beleid voeren om het potentiële inkomen naar Y* = 600 miljard te brengen. De econoom stelt: “Als consumenten minder uren gaan werken, verdwijnt de output gap.”$$, 'inline'),
  ('a4f0fdeb-b97e-4f66-bb5b-742b0ab30d33', '5468ecbd-35d4-4f38-950d-a298b66cc12e', $$inleiding: overstap van traditionele naar biologische teelt vraagt forse investering$$,
   $$economie-vwo-2025-i-groenten-context1.png$$,
   $$Een econoom onderzoekt de mogelijkheid voor boeren om over te stappen van traditioneel geteelde groente (met milieuschade) naar biologisch geteelde groente (zonder milieuschade). Dit betekent een forse investering omdat biologische telers meer grond nodig hebben om dezelfde hoeveelheid groenten te produceren. Voor de biologische teelt is dit nodig, omdat stukken grond langere tijd niet worden gebruikt, waardoor de grond langer vruchtbaar blijft.$$, 'inline'),
  ('c7f10945-87d6-4752-8db9-c6148ab94dfc', '5468ecbd-35d4-4f38-950d-a298b66cc12e', $$model voor twee boeren (zie tabellen 1 en 2)$$,
   $$economie-vwo-2025-i-groenten-context2.png$$,
   $$De econoom stelt een model op voor twee boeren om de keuze voor traditionele of biologische teelt te onderzoeken (zie tabellen 1 en 2).$$, 'inline'),
  ('4574f41b-052e-4062-8ef1-5a10f097d17b', '5468ecbd-35d4-4f38-950d-a298b66cc12e', $$tabel 1: verkoopprijs en variabele kosten per kg$$,
   $$economie-vwo-2025-i-groenten-context3.png$$,
   $$Tabel 1 verkoopprijs en variabele kosten per kg
| traditionele teelt | biologische teelt
verkoopprijs per kg | € 2,20 | € 3,00
variabele kosten per kg | € 0,75 | € 1,00$$, 'inline'),
  ('df95895d-a2ec-42b9-96e6-687a8fff6465', '5468ecbd-35d4-4f38-950d-a298b66cc12e', $$tabel 2: pay-off matrix van winsten en afzetten$$,
   $$economie-vwo-2025-i-groenten-context4.png$$,
   $$Tabel 2 pay-off matrix van behaalde winsten (in €) en afzetten (in kg)
(eerste getal: boer A; tweede getal, cursief: boer B)
| boer B traditionele teelt | boer B biologische teelt
boer A traditionele teelt | € 80.000 ; € 80.000 / 65.000 kg ; 65.000 kg | € 87.250 ; € 75.000 / 70.000 kg ; 46.050 kg
boer A biologische teelt | € 75.000 ; € 87.250 / 46.050 kg ; 70.000 kg | € 92.900 ; € 92.900 / 55.000 kg ; 55.000 kg$$, 'inline'),
  ('93498f7b-f980-4cd9-8403-22c8696622b7', '5468ecbd-35d4-4f38-950d-a298b66cc12e', $$boer B investeert in biologische teelt; oude vaste kosten € 14.250$$,
   $$economie-vwo-2025-i-groenten-context5.png$$,
   $$Stel dat boer B investeert in biologische teelt, terwijl boer A voorlopig traditioneel blijft telen. De oude vaste (constante) kosten, voordat de investering wordt gedaan, zijn € 14.250.$$, 'inline');

