   $$economie-vwo-2025-i-concurreren-met-zekerheid-vraag10.png$$, $$2p 10 Leg met behulp van figuur 1 uit dat marktwerking tot een lagere premie kan leiden.$$, array['fb91dd04-a787-47c0-b5fa-d09e479fcba1', 'd8fece83-9ee4-4850-8423-2d2baac11fe6']::uuid[]),
