   $$economie-vwo-2025-i-ijssalon-vraag14.png$$, $$4p 14 Bereken hoeveel procent van de gestegen variabele kosten wordt doorberekend in de verkoopprijs.$$, array['53daa2ea-8a2f-46a1-9484-29326ce03bff', '917fc8ae-649d-431d-b1df-bf86ec72f017', 'a191a5c1-e4e8-4481-ad8b-aaf4be759cc8']::uuid[]),
