   $$economie-vwo-2025-i-eilanden-verbonden-vraag17.png$$, $$2p 17 Bereken de arbeidsinkomensquote (AIQ) van Curaçao.$$, array['33bb6659-488f-4aa5-9916-5c29c4b19733', '3a4f95f2-7d89-4137-8d0d-0d705e4fcd1e', 'ed2fa49b-b77f-415a-9fc8-09a952f4ab69']::uuid[]),
  ('0190f1f7-b5b3-4957-9baf-e0a685fc9d65', 'a189ee78-f2a6-4f3d-8848-6ebfc8358251', 18,
   '[{"domain": "Welvaart en groei", "subdomain": "Macro-economische kringloop"}]'::jsonb,
   '["overheidssaldo berekenen", "financiële kringloop", "S = I + (O – B) + (E – M)", "begrotingstekort", "spaarsaldo"]'::jsonb,
